mapper.select:
WITH roots AS ( SELECT DISTINCT ON (run.tenant_id,run.session_id,run.root_input_id) run.tenant_id,run.session_id,run.root_input_id, run.created_second AS started_second,run.created_nano AS started_nano FROM public.agent_runtime_execution_runs run JOIN public.nw_chat_sessions session ON session.tenant_id::text=run.tenant_id AND session.session_id=run.session_id WHERE TRUE AND run.tenant_id=CAST(#{scopeTenantId} AS text) AND run.tenant_id=CAST(#{tenantId} AS text) AND run.session_id=#{sessionId}
AND EXISTS (SELECT 1 FROM public.agent_runtime_execution_runs member WHERE member.tenant_id=run.tenant_id AND member.session_id=run.session_id AND member.root_input_id=run.root_input_id AND member.agent_id=CAST(#{agentId} AS text))
AND FALSE AND run.session_id IN #{session}
ORDER BY run.tenant_id,run.session_id,run.root_input_id,run.created_second,run.created_nano,run.run_id ) SELECT tenant_id::bigint AS tenant_id,session_id,root_input_id,started_second,started_nano FROM roots WHERE (started_second,started_nano)>=(#{fromSecond},#{fromNano}) AND (started_second,started_nano)<(#{toSecond},#{toNano}) ORDER BY started_second DESC,started_nano DESC,tenant_id,session_id,root_input_id LIMIT #{limit} OFFSET #{offset}
